<?php
declare(strict_types=1);
namespace Nexus\Features\Seguridad\Application;
use Nexus\Shared\Security\PasswordHasher;use Nexus\Features\Seguridad\Domain\PasswordPolicy;use Nexus\Features\Seguridad\Domain\PendingTotpStore;use Nexus\Features\Seguridad\Domain\SeguridadCuentaRepository;use Nexus\Features\Seguridad\Domain\TotpProvider;use Nexus\Shared\Domain\ValueObject\Cedula;use Nexus\Shared\DomainException;
final class SeguridadCuentaService
{
    private const EVENTOS=['login_ok','login_fallido','login_bloqueado','2fa_fallido','2fa_activado','2fa_desactivado','2fa_restablecido','sesiones_cerradas','contrasena_cambiada','logout'];
    private SeguridadCuentaRepository $repo;private PasswordHasher $hasher;private PasswordPolicy $policy;private TotpProvider $totp;private PendingTotpStore $pendiente;
    public function __construct(SeguridadCuentaRepository $r,PasswordHasher $h,PasswordPolicy $p,TotpProvider $t,PendingTotpStore $s){$this->repo=$r;$this->hasher=$h;$this->policy=$p;$this->totp=$t;$this->pendiente=$s;}
    public function estado(Cedula $c,bool $admin,bool $obligatorio):array{$f=$this->repo->segundoFactor($c);return ['dosFactores'=>['activo'=>(string)($f['totp_secreto']??'')!=='','obligatorio'=>$admin&&$obligatorio],'esAdmin'=>$admin,'actividad'=>$this->repo->actividad($c,self::EVENTOS,15)];}
    public function iniciar(Cedula $c,string $password):array{$this->exigirPassword($c,$password);$s=$this->totp->generar();$this->pendiente->guardar($s,time());return ['ok'=>true,'secreto'=>$s,'uri'=>$this->totp->uri($s,$c->value())];}
    /* Reemplazar un factor ya enrolado exige la misma prueba que retirarlo: un codigo del factor vigente.
       Con solo la contraseña, quien tiene una sesion robada se quedaria con un segundo factor propio. */
    public function confirmar(Cedula $c,string $codigo,string $codigoVigente=''):void{$f=$this->repo->segundoFactor($c);$vigente=(string)($f['totp_secreto']??'');if($vigente!==''){$ultimo=$f['totp_ultimo_paso']===null?null:(int)$f['totp_ultimo_paso'];$pasoVigente=$this->totp->verificar($vigente,$codigoVigente,$ultimo);if($pasoVigente===null){$this->repo->registrarEvento('2fa_fallido',$c,'reemplazo del factor');throw new DomainException('Para reemplazar el segundo factor ingresa también un código del actual.',403);}$this->repo->actualizarPaso($c,$pasoVigente);}$n=$this->pendiente->obtener();if(!$n||time()-(int)($n['inicio']??0)>600){$this->pendiente->eliminar();throw new DomainException('La activación venció. Empezá de nuevo.');}$paso=$this->totp->verificar((string)$n['secreto'],$codigo,null);if($paso===null)throw new DomainException('El código no coincide. Revisa que el reloj del teléfono este en hora.');$this->repo->activarTotp($c,(string)$n['secreto'],$paso);$this->pendiente->eliminar();$this->repo->registrarEvento('2fa_activado',$c);}
    public function desactivar(Cedula $c,string $password,string $codigo,bool $bloqueado):void{if($bloqueado)throw new DomainException('Para los administradores la verificación en dos pasos es obligatoria.',403);$this->exigirPassword($c,$password);$f=$this->repo->segundoFactor($c);$ultimo=$f['totp_ultimo_paso']===null?null:(int)$f['totp_ultimo_paso'];$paso=$this->totp->verificar((string)$f['totp_secreto'],$codigo,$ultimo);if($paso===null){$this->repo->registrarEvento('2fa_fallido',$c,'gestión de cuenta');throw new DomainException('El código de verificación no es correcto.',403);}$this->repo->actualizarPaso($c,$paso);$this->repo->desactivarTotp($c);$this->repo->registrarEvento('2fa_desactivado',$c);}
    public function restablecer(Cedula $admin,Cedula $objetivo):void{if($admin->equals($objetivo))throw new DomainException('Indica la cédula de otro usuario.');if(!$this->repo->usuarioExiste($objetivo))throw new DomainException('No existe el usuario indicado.',404);$this->repo->restablecerTotp($objetivo);$this->repo->registrarEvento('2fa_restablecido',$objetivo,'por '.$admin->value());}
    public function cerrarSesiones(Cedula $c):int{$v=$this->repo->incrementarVersion($c);$this->repo->registrarEvento('sesiones_cerradas',$c);return $v;}
    public function cambiarPassword(Cedula $c,string $actual,string $nueva):int{$this->exigirPassword($c,$actual);$this->policy->validar($nueva);if(hash_equals($actual,$nueva))throw new DomainException('La nueva contraseña tiene que ser distinta de la actual.');$this->repo->cambiarPassword($c,$this->hasher->hash($nueva));$v=$this->repo->incrementarVersion($c);$this->repo->registrarEvento('contrasena_cambiada',$c);return $v;}
    private function exigirPassword(Cedula $c,string $p):void{$h=$this->repo->passwordHash($c);if($p===''||strlen($p)>1024||!$this->hasher->verify($p,$h)){$this->repo->registrarEvento('reautenticacion_fallida',$c);throw new DomainException('La contraseña actual no es correcta.',403);}}
}
